// app.js
const express = require('express');
const app = express();
// NOTE: express.json() is NOT registered

app.post('/greet', (req, res) => {
  const name = req.body.name;
  res.json({ message: `Hello, ${name}!` });
});

module.exports = app;

// app.test.js
const request = require('supertest');
const app = require('./app');

test('POST /greet greets the given name', async () => {
  const response = await request(app)
    .post('/greet')
    .send({ name: 'Amy' });

  expect(response.status).toBe(200);
  expect(response.body).toEqual({ message: 'Hello, Amy!' });
});

// app.js exports an Express app backed by an in-memory array `users`
// starting as: let users = [];

const request = require('supertest');
const app = require('./app');

describe('POST /users', () => {
  it('creates the first user with id 1', async () => {
    const response = await request(app).post('/users').send({ name: 'Amy' });
    expect(response.status).toBe(201);
    expect(response.body.id).toBe(1);
  });

  it('creates a user and the total user count is 1', async () => {
    const response = await request(app).post('/users').send({ name: 'Ben' });
    expect(response.status).toBe(201);

    const listResponse = await request(app).get('/users');
    expect(listResponse.body).toHaveLength(1);
  });
});

exercises.solutionCode:
const request = require('supertest');

describe('POST /users', () => {
  let app;

  beforeEach(() => {
    jest.resetModules();
    app = require('./app');   // fresh module instance -> fresh in-memory `users` array
  });

  it('creates the first user with id 1', async () => {
    const response = await request(app).post('/users').send({ name: 'Amy' });
    expect(response.status).toBe(201);
    expect(response.body.id).toBe(1);
  });

  it('creates a user and the total user count is 1', async () => {
    const response = await request(app).post('/users').send({ name: 'Ben' });
    expect(response.status).toBe(201);

    const listResponse = await request(app).get('/users');
    expect(listResponse.body).toHaveLength(1);
  });
});
